<script setup lang="ts">
import axios from 'axios';
import {computed,nextTick,onMounted,onUnmounted,ref} from 'vue';
import {api,errorMessage} from '../api';
import {amount} from '../catalog';
import {units,type SavedOrder} from '../sales';
import {readPending,savePending,clearPending} from '../lib/pendingRequests';
import AppDialog from './AppDialog.vue';
import {downloadPrivatePdf} from '../lib/downloadPdf';
import CreditApplicationReversal from './CreditApplicationReversal.vue';
import {creditReversalText as rt} from '../locales/es/creditReversal';
type Source={payment_id:number;origin_number:number|string;available:string;method:string;pools:{order_id:number;available:string}[]};
type Info={version:number;review_hash:string;currency:string;invoice_number:string;application_allowed:boolean;return_pending:boolean;balance:{pending_total:string;paid_total:string};sources:Source[];history:{id:number;amount:string;origin_order_id:number;payment_id:number;reason:string;actor_name:string;reversal?:{id:number;reason:string;actor_name:string;created_at:string}|null}[]};
type Pending={payload:{request_key:string;version:number;review_hash:string;payment_id:number;amount:string;reason:string}};
const props=defineProps<{root:string;actorId:number;order:SavedOrder;canApply:boolean;canDownload?:boolean;canReverseCredit?:boolean;disabled:boolean}>();const emit=defineEmits<{changed:[SavedOrder]}>();
const endpoint=`${props.root}/sales/orders/${props.order.id}/credits`;const journal=`bshop:credit-application:${props.actorId}:${props.root}:${props.order.id}`;
const open=ref(false);const busy=ref(false);const error=ref('');const notice=ref('');const info=ref<Info|null>(null);const selected=ref<number|null>(null);const value=ref('');const reason=ref('');const pending=ref<Pending|null>(null);const opener=ref<HTMLElement|null>(null);let alive=true;
const reversing=ref<number|null>(null);const reversalOpener=ref<HTMLElement|null>(null);const reversalJournal=`bshop:credit-reversal:${props.actorId}:${props.root}:${props.order.id}`;
async function reverse(id:number,event:Event){if(busy.value||pending.value||!props.canReverseCredit)return;reversalOpener.value=event.currentTarget as HTMLElement;open.value=false;await nextTick();reversing.value=id;}
async function reversalChanged(order:SavedOrder){emit('changed',order);notice.value=rt.success;try{await load();}catch(e){error.value=explain(e);}}
async function reversalClosed(){reversing.value=null;await nextTick();open.value=true;try{await load();}catch(e){error.value=explain(e);}}
const ready=computed(()=>{const source=info.value?.sources.find(s=>s.payment_id===selected.value);const n=units(value.value);const available=units(source?.available||'0');const due=units(info.value?.balance.pending_total||'0');return !!info.value?.application_allowed&&!!source&&reason.value.trim().length>=5&&n!==null&&available!==null&&due!==null&&n>0n&&n<=available&&n<=due;});
const explain=(e:unknown)=>axios.isAxiosError(e)&&e.response?.status===409&&typeof e.response.data?.message==='string'?e.response.data.message:errorMessage(e);
async function load(){const result=(await api.get(endpoint)).data.data;if(alive)info.value=result;}
async function show(event:Event){opener.value=event.currentTarget as HTMLElement;open.value=true;busy.value=true;error.value='';try{await load();}catch(e){if(alive)error.value=explain(e);}finally{if(alive)busy.value=false;}}
function choose(source:Source){if(busy.value||pending.value||!props.canApply)return;selected.value=source.payment_id;value.value=(units(source.available)||0n)>(units(info.value?.balance.pending_total||'0')||0n)?info.value!.balance.pending_total:source.available;reason.value='';notice.value='';}
async function finish(order:SavedOrder,recovered=false){if(!alive)return;pending.value=null;selected.value=null;value.value='';reason.value='';error.value='';notice.value=recovered?'Aplicación de crédito recuperada sin repetir movimientos.':'Saldo a favor aplicado. No se registró un nuevo cobro.';try{clearPending(journal);}catch{}emit('changed',order);await load();}
async function send(){if(busy.value||props.disabled||!props.canApply)return;error.value='';if(!pending.value){if(!info.value||!ready.value||!selected.value)return;const operation:Pending={payload:{request_key:crypto.randomUUID(),version:info.value.version,review_hash:info.value.review_hash,payment_id:selected.value,amount:value.value,reason:reason.value}};try{savePending(journal,operation as unknown as Record<string,unknown>);pending.value=operation;}catch{error.value='No se pudo guardar la recuperación. No se aplicó crédito.';return;}}
    busy.value=true;try{await finish((await api.post(endpoint,pending.value.payload)).data.data.order);}catch(e){if(alive){error.value=explain(e);if(axios.isAxiosError(e)&&e.response&&[409,422].includes(e.response.status)){pending.value=null;try{clearPending(journal);}catch{}}}}finally{if(alive)busy.value=false;}}
async function recover(){if(!pending.value||busy.value)return;busy.value=true;error.value='';try{await finish((await api.get(`${endpoint}/requests/${pending.value.payload.request_key}`)).data.data.order,true);}catch(e){if(alive)error.value=axios.isAxiosError(e)&&e.response?.status===404?'La aplicación no está confirmada. Reintenta los mismos datos.':explain(e);}finally{if(alive)busy.value=false;}}
async function refresh(){if(busy.value||pending.value)return;busy.value=true;error.value='';try{await load();}catch(e){if(alive)error.value=explain(e);}finally{if(alive)busy.value=false;}}
async function download(id:number){if(busy.value||pending.value||!props.canDownload)return;busy.value=true;error.value='';try{const result=(await api.post(`${props.root}/sales/orders/${props.order.id}/documents/credit/${id}`)).data.data;await downloadPrivatePdf(result.url,result.filename);}catch(e){if(alive)error.value=explain(e);}finally{if(alive)busy.value=false;}}
onMounted(async()=>{const reversingSaved=readPending(reversalJournal);if(props.canReverseCredit&&Number.isInteger(reversingSaved?.applicationId)){reversing.value=Number(reversingSaved!.applicationId);return;}const saved=readPending(journal) as unknown as Pending|null;if(saved&&typeof saved.payload?.request_key==='string'&&Number.isInteger(saved.payload.payment_id)){pending.value=saved;selected.value=saved.payload.payment_id;value.value=saved.payload.amount;reason.value=saved.payload.reason;open.value=true;busy.value=true;try{await load();}catch{}finally{busy.value=false;}await recover();}});onUnmounted(()=>{alive=false;});
</script>
<template><button type="button" class="button secondary" :disabled="busy||disabled" @click="show">Saldo a favor del cliente</button>
<AppDialog :open="open" title="Aplicar saldo a favor" :busy="busy" :return-focus="opener" @close="open=false">
    <p>Aplica crédito liberado de devoluciones conciliadas al pedido facturado de este mismo cliente, sucursal y moneda. Los depósitos vinculados a pedidos sin factura no se ofrecen como saldo libre.</p>
    <p v-if="error" class="notice error" role="alert">{{ error }}</p><p v-if="notice" class="notice success" role="status">{{ notice }}</p><p v-if="busy" role="status">Consultando saldo a favor…</p><p v-if="pending" class="notice">Operación sin respuesta confirmada: {{ pending.payload.amount }} · {{ pending.payload.reason }}. Se conserva el mismo UUID.</p>
    <template v-if="info"><p><strong>{{ info.invoice_number }}</strong> · Pendiente neto {{ amount(info.balance.pending_total,info.currency) }}</p><p v-if="!info.application_allowed" class="notice">El destino está retenido por devolución o requiere conciliación.</p>
        <section aria-label="Créditos disponibles"><article v-for="source in info.sources" :key="source.payment_id"><strong>Pago #{{ source.payment_id }} · Pedido original #{{ source.origin_number }}</strong><p>Saldo elegible {{ amount(source.available,info.currency) }} · {{ source.method }}</p><button v-if="canApply" type="button" class="button secondary" :disabled="busy||!!pending||!info.application_allowed||units(info.balance.pending_total)===0n" :aria-label="`Seleccionar crédito del pago #${source.payment_id}`" @click="choose(source)">Seleccionar crédito</button></article><p v-if="!info.sources.length&&!busy" class="muted">No hay saldo liberado elegible disponible.</p></section>
        <fieldset v-if="selected&&canApply" class="form-fields" :disabled="busy||!!pending"><label>Importe de crédito a aplicar<input :value="value" inputmode="decimal" maxlength="20" @input="value=($event.target as HTMLInputElement).value.replace(',','.')"></label><label>Motivo de la aplicación<textarea v-model="reason" minlength="5" maxlength="255" rows="3"></textarea></label></fieldset>
        <section aria-label="Aplicaciones de crédito anteriores"><h3>Aplicaciones recibidas</h3><article v-for="entry in info.history" :key="entry.id"><strong>#{{ entry.id }} · {{ amount(String(entry.amount),info.currency) }}</strong><p>Pago #{{ entry.payment_id }} · Origen #{{ entry.origin_order_id }} · {{ entry.actor_name }}</p><p>{{ entry.reason }}</p><p v-if="entry.reversal" class="notice">{{ rt.historyReversed }} · {{ entry.reversal.reason }} · {{ entry.reversal.actor_name }} · {{ entry.reversal.created_at }}</p><button v-if="canDownload" type="button" class="button secondary" :disabled="busy||!!pending" :aria-label="`Descargar comprobante de crédito #${entry.id}`" @click="download(entry.id)">Descargar comprobante</button><button v-if="canReverseCredit&&!entry.reversal" type="button" class="button secondary" :disabled="busy||!!pending||disabled" :aria-label="rt.actionAria(entry.id)" @click="reverse(entry.id,$event)">{{ rt.action }}</button></article></section>
    </template>
    <button v-if="pending" type="button" class="button secondary" :disabled="busy" @click="recover">Comprobar aplicación de crédito</button><button v-else type="button" class="button secondary" :disabled="busy" @click="refresh">Actualizar revisión de crédito</button>
    <template #footer><button type="button" class="button secondary" :disabled="busy" @click="open=false">Cerrar</button><button v-if="canApply&&(selected||pending)" type="button" class="button primary" :disabled="busy||disabled||(!pending&&!ready)" @click="send">{{ pending?'Reintentar aplicación de crédito':'Aplicar crédito al pedido' }}</button></template>
</AppDialog><CreditApplicationReversal v-if="reversing" :root="root" :actor-id="actorId" :order-id="order.id" :application-id="reversing" :return-focus="reversalOpener" @changed="reversalChanged" @closed="reversalClosed"/></template>
<style scoped>article{padding:16px 0;border-bottom:1px solid #e4ddec}p,strong{overflow-wrap:anywhere}h3,fieldset{margin-top:20px}fieldset{padding-top:16px}</style>
